/* Palette: #1e1e2f (bg), #2a2a40 (card), #e0e0ff (text), #6c5ce7 (accent), #00d2d3 (highlight) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: #1e1e2f;
  color: #e0e0ff;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #2a2a40;
  border-radius: 12px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.8rem;
  text-align: center;
  margin-bottom: 24px;
  color: #00d2d3;
  letter-spacing: 1px;
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

label {
  font-weight: 600;
  font-size: 1rem;
}

input[type="number"] {
  background: #1e1e2f;
  border: 2px solid #6c5ce7;
  border-radius: 8px;
  color: #e0e0ff;
  font-size: 1.1rem;
  padding: 10px 12px;
  width: 100%;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input[type="number"]:focus {
  outline: none;
  border-color: #00d2d3;
  box-shadow: 0 0 0 3px rgba(0, 210, 211, 0.3);
}

button {
  background: #6c5ce7;
  border: none;
  border-radius: 8px;
  color: #fff;
  cursor: pointer;
  font-size: 1.1rem;
  font-weight: 600;
  padding: 12px 16px;
  transition: background 0.2s, transform 0.1s;
}

button:hover {
  background: #5a4bd1;
}

button:focus-visible {
  outline: 3px solid #00d2d3;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
}

.display {
  text-align: center;
  margin-bottom: 24px;
}

.phase {
  font-size: 1.4rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 8px;
  color: #00d2d3;
}

.round {
  font-size: 1.2rem;
  margin-bottom: 8px;
}

.timer {
  font-size: 3rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  letter-spacing: 4px;
  color: #e0e0ff;
}

.progress {
  height: 12px;
  background: #1e1e2f;
  border-radius: 6px;
  overflow: hidden;
  position: relative;
}

.progress::after {
  content: '';
  display: block;
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #6c5ce7, #00d2d3);
  transition: width 0.3s linear;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .timer {
    font-size: 2.5rem;
  }
}

const workInput = document.getElementById('work');
const restInput = document.getElementById('rest');
const roundsInput = document.getElementById('rounds');
const startBtn = document.getElementById('start');
const resetBtn = document.getElementById('reset');
const phaseEl = document.getElementById('phase');
const roundEl = document.getElementById('round');
const timerEl = document.getElementById('timer');
const progressEl = document.getElementById('progress');

let timerId = null;
let endTime = 0;
let phase = 'idle'; // 'work', 'rest', 'complete'
let currentRound = 0;
let totalRounds = 0;
let workSeconds = 0;
let restSeconds = 0;
let phaseDuration = 0;
let phaseStartTime = 0;

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function updateDisplay(remaining) {
  timerEl.textContent = formatTime(Math.ceil(remaining));
  const elapsed = phaseDuration - remaining;
  const percent = phaseDuration > 0 ? Math.min(100, (elapsed / phaseDuration) * 100) : 0;
  progressEl.style.setProperty('--progress', percent + '%');
  progressEl.setAttribute('aria-valuenow', Math.round(percent));
}

function startPhase(newPhase, duration) {
  phase = newPhase;
  phaseDuration = duration;
  phaseStartTime = performance.now();
  endTime = phaseStartTime + duration * 1000;
  if (newPhase === 'work') {
    phaseEl.textContent = 'Work';
  } else if (newPhase === 'rest') {
    phaseEl.textContent = 'Rest';
  }
  updateDisplay(duration);
}

function tick() {
  const now = performance.now();
  const remaining = (endTime - now) / 1000;
  if (remaining <= 0) {
    if (phase === 'work') {
      if (restSeconds > 0) {
        startPhase('rest', restSeconds);
      } else {
        nextRound();
      }
    } else if (phase === 'rest') {
      nextRound();
    }
  } else {
    updateDisplay(remaining);
  }
}

function nextRound() {
  currentRound++;
  if (currentRound > totalRounds) {
    completeWorkout();
  } else {
    roundEl.textContent = `Round: ${currentRound} / ${totalRounds}`;
    startPhase('work', workSeconds);
  }
}

function completeWorkout() {
  clearInterval(timerId);
  timerId = null;
  phase = 'complete';
  phaseEl.textContent = 'Workout complete';
  roundEl.textContent = '';
  timerEl.textContent = '00:00';
  progressEl.style.setProperty('--progress', '100%');
  progressEl.setAttribute('aria-valuenow', '100');
  startBtn.hidden = false;
  resetBtn.hidden = true;
}

function startWorkout() {
  workSeconds = Math.max(1, parseInt(workInput.value) || 30);
  restSeconds = Math.max(0, parseInt(restInput.value) || 15);
  totalRounds = Math.max(1, parseInt(roundsInput.value) || 3);
  currentRound = 1;
  roundEl.textContent = `Round: ${currentRound} / ${totalRounds}`;
  startBtn.hidden = true;
  resetBtn.hidden = false;
  startPhase('work', workSeconds);
  timerId = setInterval(tick, 100);
}

function resetWorkout() {
  clearInterval(timerId);
  timerId = null;
  phase = 'idle';
  phaseEl.textContent = 'Ready';
  roundEl.textContent = 'Round: 0';
  timerEl.textContent = '00:00';
  progressEl.style.setProperty('--progress', '0%');
  progressEl.setAttribute('aria-valuenow', '0');
  startBtn.hidden = false;
  resetBtn.hidden = true;
}

startBtn.addEventListener('click', startWorkout);
resetBtn.addEventListener('click', resetWorkout);

// Initialize progress bar via CSS variable
progressEl.style.setProperty('--progress', '0%');
// Override the pseudo-element width using the variable
const style = document.createElement('style');
style.textContent = '.progress::after { width: var(--progress, 0%); }';
document.head.appendChild(style);
